    def as_pos(v):
        if isinstance(v, dict):
            if is_num(v.get("x")) and is_num(v.get("y")):
                return (int(v.get("x")), int(v.get("y")))
            p = v.get("pos", v.get("position", v.get("loc")))
            if isinstance(p, (list, tuple)) and len(p) >= 2 and is_num(p[0]) and is_num(p[1]):
